export const getSaveStrategyUrl = (id: number,) => {




  return `/api/farms/${id}/strategies`
}

export const saveStrategy = async (id: number,
    strategyInput: StrategyInput, options?: Parameters<typeof customFetch>[1]): Promise<Strategy> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Strategy>(getSaveStrategyUrl(id),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(strategyInput)
  }
);}





export const getSaveStrategyMutationKey = () => ['saveStrategy'] as const;

export const getSaveStrategyMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof saveStrategy>>, TError,SaveStrategyMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof saveStrategy>>, TError,SaveStrategyMutationVariables, TContext> => {

const mutationKey = getSaveStrategyMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof saveStrategy>>, SaveStrategyMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  saveStrategy(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SaveStrategyMutationResult = NonNullable<Awaited<ReturnType<typeof saveStrategy>>>
    export type SaveStrategyMutationBody = BodyType<StrategyInput>
    export type SaveStrategyMutationError = ErrorType<unknown>
    export type SaveStrategyMutationVariables = {id: number;data: BodyType<StrategyInput>}

    export const useSaveStrategy = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof saveStrategy>>, TError,SaveStrategyMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof saveStrategy>>,
        TError,
        SaveStrategyMutationVariables,
        TContext
      > => {
      return useMutation(getSaveStrategyMutationOptions(options), queryClient);
    }

